    "pub_date": "2026-09-07 08:23:48",
    "author": "",
    "description": "上市公司半年报披露完毕，百亿私募的重仓图谱得以清晰展现。私募排排网数据显示，共55家百亿私募出现在264家上市公司前十大流通股东名单中，合计持股市值达913.51亿元。行业配置上，食品饮料持股市值居首，电子、计算机分列二三位，呈“守红利、攻科技”的哑铃型配置格局。展望后市，多家私募机构认为，半年报披露后市场正从“情绪驱动”转向“业绩验证”，下半年投资重心应聚焦业绩确定性与产业趋势清晰的细分方向。（经济参考报）",
    "content": "上市公司半年报披露完毕，百亿私募的重仓图谱得以清晰展现。私募排排网数据显示，共55家百亿私募出现在264家上市公司前十大流通股东名单中，合计持股市值达913.51亿元。行业配置上，食品饮料持股市值居首，电子、计算机分列二三位，呈“守红利、攻科技”的哑铃型配置格局。展望后市，多家私募机构认为，半年报披露后市场正从“情绪驱动”转向“业绩验证”，下半年投资重心应聚焦业绩确定性与产业趋势清晰的细分方向。（经济参考报）"
