    "content": "新华社纽约9月6日电（记者徐静）一架亚马逊公司货机6日在美国迈阿密国际机场降落时冲出跑道，撞上车辆并起火，造成5人死亡、5人受伤，其中三人伤势严重。 迈阿密-戴德县警长罗茜·科德罗-斯图茨在新闻发布会上说，这架货机于当天13时58分冲出跑道后发生碰撞。迈阿密-戴德县县长丹妮拉·莱文·卡瓦说，5名伤者已被送往医院。 当地媒体发布的视频显示，飞机冒出滚滚浓烟，但大部分结构基本完好。据迈阿密-戴德县消防局消息，该局派出消防员灭火。 美国联邦航空局发表声明说，这架波音767-300货机从波多黎各起飞，该局将对这起事故展开调…"
