    "content": "一枚经过基因改造的猪肾使一名器官衰竭患者在等待合适人类供体肾脏期间，9个月不用进行透析治疗。这表明，在漫长的移植器官等待过程中，猪肾移植可以作为临时措施，并且未来或许能够成为永久性的替代方案。相关研究9月3日发表于《柳叶刀》。 2025年1月移植到Andrews体内的猪肾。图片来源：美国马萨诸塞州总医院 对于患有严重肾病、肾脏衰竭且需要透析的患者来说，肾移植提供了最佳的生存机会和更高的生活质量。然而，目前供体器官供不应求。一种可能的解决方案便是异种移植，即将其他动物的器官移植到人类身上。 2022年1月，全球首例猪…"
