    "description": "36氪获悉，海大集团在券商策略会表示，上半年，公司海外地区饲料销量保持高速增长，增速超25%，海外饲料市场整体集中度偏低，市场由综合农业及食品加工商主导，头部企业以全产业链布局为主，尚未出现跨区域、跨品类的绝对巨头，竞争格局相对稳定。然而，原材料价格的大幅上涨给海外饲料企业带来了短期的成本扰动，尤其是鱼粉价格创出历史新高，东南亚、拉丁美洲等水产养殖重点区域饲料企业短期普遍面临成本压力。",
