    "content": "36氪获悉，华泰证券研报称，市场普遍将钠电视为锂价高企时的对冲品种，认为锂价回落后钠电经济性不再成立，而华泰证券认为钠电的产业逻辑已从锂价对冲切换到自身经济性：目前钠电池产业化信号已明确，且未来降本路线清晰，差异化优势催生应用场景，钠电产业化进程逐步与锂价脱钩。华泰证券测算五大应用场景在2026年—2030年先后达成平价，钠电需求在2030年/2035年可达800/2047GWh，其中储能贡献接近八成。节奏上，2027年—2028年是产能与订单的验证窗口，2029年之后进入规模释放期。看好钠电需求的放量带来的产业链…"
