    "content": "新华社德黑兰9月6日电 据伊朗伊斯兰共和国广播电视台6日报道，伊朗最高国家安全委员会秘书穆赫辛·雷扎伊说，伊朗将宣布在霍尔木兹海峡之外设立一个禁区，进入船只将受到制裁。 雷扎伊接受采访时说，伊朗将在未来数日公布这一新设立的禁区，范围将从美国海军“封锁线”延伸至波斯湾部分海域，任何进入这一范围的船只都将被伊方列入制裁名单。 雷扎伊还表示，美国总统特朗普声称霍尔木兹海峡仍处于开放状态是“谎言”。美方正试图投入大量资金，以“走私方式”让船只通过有关海域，这些船只通常会遭到伊方打击。伊朗目前没有决定击沉这些船只，因为它们装…"
