    "author": "澎湃新闻记者 廖阳",
    "description": "首演于1965年的《长征组歌》，曾在几代人的耳畔响起。这部伴随着泪水诞生的大型声乐套曲，由作词萧华和四位作曲家联袂打造，如今依然久演不衰。 今年适逢红军长征胜利90周年，《长征组歌》再次响彻祖国大地，一批又一批年轻人重唱红色经典、重燃长征精神。 2026年3月在上海，上海之春国际音乐节上演《长征组歌》 边写边落泪，泪水打湿了一页页稿纸 有“儒将”之称的萧华，亲历过长征。1964年，萧华因肝炎在杭州休养。长征胜利30周年快到了，记者们纷纷…",
    "content": "首演于1965年的《长征组歌》，曾在几代人的耳畔响起。这部伴随着泪水诞生的大型声乐套曲，由作词萧华和四位作曲家联袂打造，如今依然久演不衰。 今年适逢红军长征胜利90周年，《长征组歌》再次响彻祖国大地，一批又一批年轻人重唱红色经典、重燃长征精神。 2026年3月在上海，上海之春国际音乐节上演《长征组歌》 边写边落泪，泪水打湿了一页页稿纸 有“儒将”之称的萧华，亲历过长征。1964年，萧华因肝炎在杭州休养。长征胜利30周年快到了，记者们纷纷联系他，约他写纪念文章。萧华心想：与其零散地写文章，不如写一组诗，把长征完整地记…"
