    "description": "“一个外地人来到郓城，你问他是来做什么的，他多半会说是来看酒瓶的。那时，人人都是业务员。”瑞升玻璃总经理刘磊回忆起2009年自己入行时的情形说。 十几年过去，山东郓城早已不是那个靠业务员“跑瓶子”的小县城。如今的郓城全县有500多家酒类包装企业、近10万从业人员，每年生产21亿只酒瓶和82亿只瓶盖，瓶盖产能占全国30%，酒瓶占全国15%到20%。2026年上半年，规上包装印刷企业完成产值19.5亿元，税收突破5000万元。在淘宝卖玻璃瓶…",
    "content": "“一个外地人来到郓城，你问他是来做什么的，他多半会说是来看酒瓶的。那时，人人都是业务员。” 瑞升玻璃 总经理刘磊回忆起2009年自己入行时的情形说。 十几年过去，山东郓城早已不是那个靠业务员“跑瓶子”的小县城。如今的郓城全县有500多家酒类包装企业、近10万从业人员，每年生产21亿只酒瓶和82亿只瓶盖，瓶盖产能占全国30%，酒瓶占全国15%到20%。2026年上半年，规上包装印刷企业完成产值19.5亿元，税收突破5000万元。在淘宝卖玻璃瓶的前十家企业里，有六家是郓城的。 海报设计&nbsp; 郁斐 白酒行业走低，…"
