    "content": "06/09/2026 - 19:16 法新社9月6日马格德堡消息，据公共广播电视机构的估算，德国极右翼政党选择党周日在萨克森-安哈尔特州选举中取得历史性胜利，并给保守派总理默茨以沉重打击，但该党仍需等待才能确定是否能在这个前东德联邦州执政。 反移民、亲俄且支持特朗普的“德国选择党”（AfD）在2025年的联邦议会选举中已成为该国第一大反对党。 根据ARD和ZDF电视台在投票站出口进行的民调显示，该党得票率在44%至44.5%之间，大幅领先于得票率为18.5%的保守派（基民盟）。如果这些结果得到证实，极右翼政党将在州…"
