    "content": "新华社达喀尔9月6日电（记者陈晨 齐琪）普拉亚消息：佛得角政府6日宣布，全国哀悼两天，悼念在该国南部福古岛严重交通事故中遇难的25人。 据佛得角政府通过的决议，全国哀悼从6日零时开始。其间，全国公共建筑以及佛得角驻外外交和领事机构降半旗，并取消演出和公共庆祝活动。 佛得角总理弗朗西斯科·卡瓦略6日抵达福古岛。他表示，涉事车辆共载有的39人中，25人死亡、14人受伤，两名伤者伤势较重。 卡瓦略说，政府已成立危机应对小组，并向福古岛派遣一支约16人的医疗队。 佛得角总统内韦斯当天也前往福古岛，慰问遇难者家属、出席遇难者…"
