    "title": "法国首座印度教BAPS寺庙开光典礼 数千印度教徒云集巴黎 - RFI - 法国国际广播电台",
    "link": "https://www.rfi.fr/cn/%E5%9B%BD%E9%99%85/20260906-%E6%B3%95%E5%9B%BD%E9%A6%96%E5%BA%A7%E5%8D%B0%E5%BA%A6%E6%95%99baps%E5%AF%BA%E5%BA%99%E5%BC%80%E5%85%89%E5%85%B8%E7%A4%BC-%E6%95%B0%E5%8D%83%E5%8D%B0%E5%BA%A6%E6%95%99%E5%BE%92%E4%BA%91%E9%9B%86%E5%B7%B4%E9%BB%8E",
