    "content": "“配料表的长短取决于食品的种类和企业对产品的设计，与产品的安全性和营养没有必然联系。建议大家不要盲目追求‘配料表短’。” 9月6日在北京举行的2026食品与健康传播大会上，国家食品安全风险评估中心总顾问陈君石说。 本次大会以“倡导健康文明生活方式”为主题，食品安全、食品健康科普等议题成为与会专家关注的重点。 “很多人不知道，高盐饮食是骨质疏松的重要诱因。”中国疾病预防控制中心营养学首席专家丁钢强建议，减盐首先要减少厨房里的食盐用量。烹饪时用限盐勺、起锅放盐、以天然香料提味。同时警惕酱油、咸菜等“隐形盐”，选购低钠食…"
