    "content": "背景交代一下：平时主力系统是 Linux ，业余最大的爱好就是折腾折腾自建影音，服务器上跑着 Jellyfin 和 Emby 。播放器这块，很多年前就习惯了 MPV ，自己一点点调教了着色器、画质脚本和键位，用顺手了真换不掉。 但长期以来一直有个挺膈应人的痛点： 在桌面端（尤其是 Linux 下），想找个既顺眼、又符合日常使用习惯的客户端，实在太难了。官方客户端不是很好用，自动跳过片头片尾和自动匹配字幕功能几乎没有，而且根本用不上我本地现成的 MPV 配置和各种脚本。 找了一圈没发现完全称心如意的，索性发挥程序员的…"
