    "content": "新华社北京9月6日电 题：添衣迎秋 北方地区降雨降温 新华社记者刘诗平 中央气象台6日预报，6日至9日，我国北方地区受冷空气影响，出现明显的降雨、降温过程，部分地区在大风、降温后秋凉感明显。 未来三至四天，青海、甘肃、宁夏、陕西、内蒙古、黑龙江，以及华北大部、四川盆地西部，预计先后有小到中雨，局地大到暴雨，并伴有雷电、短时强降水或冰雹等对流性天气。 气温方面，西北地区东部、华北、东北地区预计将有4℃至6℃降温，局地将达到8℃至10℃，并伴有4级至5级风，阵风6级至7级。 “此次天气过程期间，地面冷高压势力较强，冷空…"
