    "content": "终于下班了。 大龄程序员转销售，第三天。今天的结果嘛……还是收获寥寥。 该拒绝的还是拒绝，该摆手的还是摆手。愿意停下来聊的学生，也没有突然变多。 但回来的路上，我发现自己确实有了一点变化： 我已经没那么怕被拒绝了。 现在走过去，对方说不需要，我基本能自然地回一句“好，没事”，然后去找下一个，不会再因为一次拒绝纠结很久。 可新的尴尬来了。 有些学生愿意停下来，我却不知道接着说什么。 第一天的时候，最大的压力是“不敢过去”。 看到一个陌生学生，心里就开始纠结： “要不要去？” “他会不会觉得我很烦？” “万一直接拒绝我…"
