    "content": "新华社科威特城9月6日电（记者尹炣）亚丁消息：也门政府军与胡塞武装在塔伊兹省和荷台达省持续交火6日进入第4天。据双方医疗方面人士透露，此轮交火已造成至少117人死亡。 一名随政府军在西海岸前线行动的高级医疗官员6日告诉新华社记者，自本轮冲突3日爆发以来，已有54名政府军士兵死亡，另有多人受伤。截至目前，战事仍在升级，暂无缓和迹象。而据荷台达省西部由胡塞武装控制的医院的医疗人士透露，此轮交火已造成63名胡塞武装人员死亡。 也门政府军部队6日在社交媒体发表声明称，其与胡塞武装在塔伊兹省西南部和西部地区的战斗时断时续，并…"
