    "author": "",
    "description": "",
    "content": "快科技9月6日消息，据报道， 一位名为erek的海外用户在测试DLSS 5神经渲染时，其RTX 5090显卡的16针供电接口发生熔毁。 测试场景为NBA 2K27，这也是目前唯一官方支持DLSS 5的游戏，erek记录的功耗变化显示，开启DLSS 5后，GPU功耗从约450W飙升至600W以上。 GPU-Z截图显示板功耗峰值达到613.5W，且erek表示显卡在610W以上维持了一段时间，而非瞬间峰值，而这张显卡的功耗上限为575W。 需要注意的是，GPU-Z报告的是整板功耗，包含PCIe插槽供电，并非全部通过16…"
