    "description": "新华社北京9月6日电 题：携手同心 不断推进中埃命运共同体建设——埃及各界人士高度评价习近平主席国事访问 新华社记者 近日，国家主席习近平圆满结束对埃及的国事访问。埃及各界人士在接受新华社记者采访时表示，习近平主席时隔10年再访埃及，赓续了传统友谊，加深了政治互信，拓展了互利合作空间。在元首外交引领下，两大文明古国跨越亚非大陆相向而行，不断推进命运共同体建设。 习近平主席此次访问埃及，适逢中埃建交70周年。塞西总统高度重视此访，亲自设计…",
    "content": "新华社北京9月6日电 题：携手同心 不断推进中埃命运共同体建设——埃及各界人士高度评价习近平主席国事访问 新华社记者 近日，国家主席习近平圆满结束对埃及的国事访问。埃及各界人士在接受新华社记者采访时表示，习近平主席时隔10年再访埃及，赓续了传统友谊，加深了政治互信，拓展了互利合作空间。在元首外交引领下，两大文明古国跨越亚非大陆相向而行，不断推进命运共同体建设。 习近平主席此次访问埃及，适逢中埃建交70周年。塞西总统高度重视此访，亲自设计访问日程，偕夫人在机场为习近平主席夫妇举行富有浓郁埃及特色的欢迎仪式。抵达当天，…"
