    "description": "中新网合肥9月6日电 (记者 任帅 张强 储玮玮)9月6日晚，2026“把青春华章写在祖国大地上”大思政课网络主题宣传和互动引导活动在中国科学技术大学举行。演员马少骅赞叹：安徽了不起，中国文房四宝安徽占三宝。其中，宣纸的历史有1200多年，也就是在唐朝的时候就有了。他说，宣纸制作有108道工序，“创造宣纸的人，就是当时中国的具有创造性的科学家。”",
