    "title": "“欧佩克+”主要产油国决定保持10月产量不变",
    "link": "http://www.news.cn/20260906/d9e060bd339b460596d413644a1345f2/c.html",
    "pub_date": "2026-09-06 22:39:28",
    "author": "孟凡宇",
    "description": "新华社维也纳9月6日电（记者孟凡宇）石油输出国组织（欧佩克）6日发表声明说，7个“欧佩克+”主要产油国决定保持10月原油产量不变，与9月水平相同，并重申维护市场稳定。 沙特阿拉伯、俄罗斯、伊拉克、科威特、哈萨克斯坦、阿尔及利亚和阿曼的代表当天举行线上会议，研判全球石油市场现状与前景。这是主要产油国今年4月启动增产以来，首次暂停增产。 有媒体报道说，中东战事使霍尔木兹海峡石油运输受阻，限制了“欧佩克+”对油价和市场份额的影响力。“欧佩克+…",
    "content": "新华社维也纳9月6日电（记者孟凡宇）石油输出国组织（欧佩克）6日发表声明说，7个“欧佩克+”主要产油国决定保持10月原油产量不变，与9月水平相同，并重申维护市场稳定。 沙特阿拉伯、俄罗斯、伊拉克、科威特、哈萨克斯坦、阿尔及利亚和阿曼的代表当天举行线上会议，研判全球石油市场现状与前景。这是主要产油国今年4月启动增产以来，首次暂停增产。 有媒体报道说，中东战事使霍尔木兹海峡石油运输受阻，限制了“欧佩克+”对油价和市场份额的影响力。“欧佩克+”今年晚些时候将评估各产油国的石油产能，以设定2027年的产量基准。 “欧佩克+…"
