    "content": "Astra 出来大受震撼，准备开始蹬 GPT-6 做 App 了。 看了下过往帖子，发现上架应用商店好像蛮麻烦的。 目前了解到： ios 似乎只要交$99 ，别的都不用管 国产安卓平台需要注册企业，搞 ICP 认证，软著，可能还有资质认证 想问问有经验的大大们，App 做好以后，上架应用商店需要做哪些事情呢？ 怎么搞定这么多认证文件呢？"
